await page.goto('https://www.nist.gov/pml/owm/metric-si');
await page.evaluate(() => {
  const text = document.body.innerText;
  const match = text.match(/deka[\s\S]{0,100}/i);
  return cu.claim({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: match?.[0] || 'Metric prefixes', values: [...document.querySelectorAll('tr')].map(r => r.innerText).filter(x => /deka/i.test(x)), answer: (() => { const row = [...document.querySelectorAll('tr')].find(r => /deka/i.test(r.innerText)); return row?.innerText || match?.[0] || ''; })()});
});

await page.goto('https://www.nist.gov/pml/owm/metric-si-prefixes');
await page.evaluate(() => {
 const text = document.body.innerText;
 const lines = text.split('\n').map(s => s.trim()).filter(Boolean);
 const idx = lines.findIndex(s => /^deka$/i.test(s));
 let rowText = '';
 if (idx >= 0) rowText = lines.slice(Math.max(0, idx-2), idx+4).join(' | ');
 const row = [...document.querySelectorAll('tr')].find(r => /deka/i.test(r.innerText));
 const evidence = row?.innerText || rowText || text.match(/deka.{0,120}/i)?.[0] || '';
 const symbol = row ? [...row.querySelectorAll('td,th')].map(c=>c.innerText.trim()).find((v,i)=>i>0 && /^[a-zA-Z]+$/.test(v)) : (lines[idx+1] || '');
 return cu.claim({url:location.href,title:document.title,h1:document.querySelector('h1')?.innerText,key_text:evidence,values:[evidence],answer:symbol});
});
